import { test, expect } from '@playwright/test';
import { createAccount, deleteAccount } from './support/api';

test.describe('checkout', () => {
  let account: Account;

  // Own data per test. Shared fixtures are why suites cannot run in parallel.
  test.beforeEach(async () => { account = await createAccount(); });
  test.afterEach(async () => { await deleteAccount(account.id); });

  test('a guest can buy the last item in stock', async ({ page }) => {
    await page.goto(`/products/${account.seededSku}`);

    // By role and name, as a user finds it. Not '.btn-primary', which is a
    // styling decision nobody promised to keep.
    await page.getByRole('button', { name: 'Add to cart' }).click();
    await page.getByRole('link', { name: 'Checkout' }).click();

    await page.getByLabel('Email').fill(account.email);
    await page.getByLabel('Delivery address').fill('Road 6, Dhaka 1207');
    await page.getByRole('button', { name: 'Pay now' }).click();

    // Web-first assertion: retries until true or fails with what it saw.
    // No waitForTimeout - a fixed sleep is either flaky or slow, usually both.
    await expect(
      page.getByRole('heading', { name: 'Order confirmed' }),
    ).toBeVisible();

    // The rule that matters, asserted where a user can see it.
    await expect(page.getByText('Out of stock')).toBeVisible();
  });
});
